// ResidualIssue Warning that a cancelled or failed build may have left the machine needing
// manual cleanup. Present on `BuildDetails`, the SSE terminal event, and a
// cancel response.
type ResidualIssue struct {
	// Detail Remediation detail: the failing signal error, or the tool's residual
	// cleanup report including its `mount | grep` / `losetup -l` hint.
	Detail string `json:"detail"`

	// Kind - `cancellation-failure` — the cancel signal could not be delivered (or
	//   the build never exited), so teardown may never have run.
	// - `cleanup-failure` — the build ran its teardown but reported leftover
	//   mounts or loop devices.
	Kind ResidualIssueKind `json:"kind"`
}

// ResidualIssueKind - `cancellation-failure` — the cancel signal could not be delivered (or
//
//		the build never exited), so teardown may never have run.
//	  - `cleanup-failure` — the build ran its teardown but reported leftover
//	    mounts or loop devices.
type ResidualIssueKind string

